effect.script:
function animate(env, el, p) {
var t = env.frame / env.fps;
var freq = p.gamma * p.beta;
el.transform.location.x += Math.sin(t * freq)         * p.Xmag;
el.transform.location.y += Math.sin(t * freq + 1.047) * p.Ymag * 0.7;
el.transform.angle      += Math.sin(t * freq + 2.094) * p.rotMag;
return el;
}
